"use client"

import * as React from "react"
import * as MenuPrimitive from "@radix-ui/react-dropdown-menu"

import { marginaliaUnder } from "@/lib/0nlytype/menu-room"
import { useComposedRefs } from "@/lib/0nlytype/refs"
import { cn } from "@/lib/utils"

// Radix reads direction from its own provider, not the page, so on a right-to-left page a menu
// would hang from the wrong end and its arrow keys would run the wrong way round. Without a dir,
// the menu takes the direction of the page around its trigger, read as the trigger mounts (as the
// menubar and the toggle group do). The root renders nothing, so the trigger reports it.
const Around = React.createContext<(dir: "rtl") => void>(() => {})

function DropdownMenu({ dir, ...props }: React.ComponentProps<typeof MenuPrimitive.Root>) {
  const [around, setAround] = React.useState<"rtl">()
  return (
    <Around.Provider value={setAround}>
      <MenuPrimitive.Root data-slot="dropdown-menu" dir={dir ?? around} {...props} />
    </Around.Provider>
  )
}

function DropdownMenuTrigger({ ref, ...props }: React.ComponentProps<typeof MenuPrimitive.Trigger>) {
  const setAround = React.useContext(Around)
  const composedRef = useComposedRefs(React.useCallback((node: HTMLButtonElement | null) => {
    if (node && getComputedStyle(node).direction === "rtl") setAround("rtl")
  }, [setAround]), ref)
  return (
    <MenuPrimitive.Trigger
      ref={composedRef}
      data-slot="dropdown-menu-trigger"
      {...props}
    />
  )
}

function DropdownMenuGroup(props: React.ComponentProps<typeof MenuPrimitive.Group>) {
  return <MenuPrimitive.Group data-slot="dropdown-menu-group" {...props} />
}

function DropdownMenuRadioGroup(props: React.ComponentProps<typeof MenuPrimitive.RadioGroup>) {
  return <MenuPrimitive.RadioGroup data-slot="dropdown-menu-radio-group" {...props} />
}

function DropdownMenuSub(props: React.ComponentProps<typeof MenuPrimitive.Sub>) {
  return <MenuPrimitive.Sub data-slot="dropdown-menu-sub" {...props} />
}

/**
 * How a menu's list is set. `list`: the item you point at is marked with the highlighter.
 * `leaders`: a book's contents page; each word is joined to its keys by leader dots, and the
 * leader of the word you point at inks from the word to its keys. `marginalia` (dropdown
 * only): the word you point at is explained by a small note hung beside the list on a hairline
 * arrow (each item's `hint`). `orbit` (context menu only): the words stand on an arc.
 * Submenus inherit leaders; the other looks keep to their own list.
 */
type MenuVariant = "list" | "leaders" | "marginalia" | "orbit"
const MenuLook = React.createContext<MenuVariant>("list")

type Note = { hint?: string; y: number; under: boolean }

/**
 * Marginalia: the note for the item you point at, set beside the list at that item's height
 * (or under the list, where there's no room beside it). Radix focuses the item you point at or
 * arrow to, so focus tells us which one. Focus from a submenu bubbles here through React, so
 * only this menu's own items count.
 */
function useMarginalia(on: boolean) {
  const [note, setNote] = React.useState<Note>({ y: 0, under: false })
  const onFocus = (event: React.FocusEvent<HTMLDivElement>) => {
    const menu = event.currentTarget, item = (event.target as HTMLElement).closest<HTMLElement>("[role^='menuitem']")
    if (!on || !item || item.closest("[role='menu']") !== menu) return
    const under = marginaliaUnder(menu.getBoundingClientRect(), document.documentElement.clientWidth, getComputedStyle(menu).direction)
    setNote({ hint: item.dataset.hint, y: item.offsetTop + item.offsetHeight / 2, under })
  }
  const el = on ? (
    <div className="ot-menu-note" aria-hidden data-under={note.under ? "" : undefined} data-empty={note.hint ? undefined : ""} style={{ "--ot-note-y": `${note.y}px` } as React.CSSProperties}>
      {note.hint}
    </div>
  ) : null
  return { onFocus, el }
}

/**
 * A list of words on the popover panel, hung from its trigger on a leader line. The word
 * you point at is marked with the highlighter; the words arrive in turn.
 */
function DropdownMenuContent({
  className,
  align = "start",
  sideOffset = 27, /* --ot-space-5: the leader is this long */
  collisionPadding = 20,
  variant = "list",
  style,
  onFocus,
  children,
  ...props
}: React.ComponentProps<typeof MenuPrimitive.Content> & { variant?: "list" | "leaders" | "marginalia" }) {
  const margin = useMarginalia(variant === "marginalia")
  return (
    <MenuPrimitive.Portal>
      <MenuPrimitive.Content
        data-slot="dropdown-menu-content"
        data-variant={variant}
        align={align}
        sideOffset={sideOffset}
        collisionPadding={collisionPadding}
        style={{ "--ot-pop-gap": `${sideOffset}px`, ...style } as React.CSSProperties}
        className={cn("ot-pop ot-menu", className)}
        onFocus={(event) => (onFocus?.(event), margin.onFocus(event))}
        {...props}
      >
        <MenuLook.Provider value={variant}>{children}</MenuLook.Provider>
        {margin.el}
      </MenuPrimitive.Content>
    </MenuPrimitive.Portal>
  )
}

/** An item's `hint`: the note marginalia hangs beside it, and its description for screen readers. */
const hinted = (hint?: string) => (hint ? { "data-hint": hint, "aria-description": hint } : {})

/** A destructive item says so in its words ("Delete Halden for good"); it is never red. */
function DropdownMenuItem({
  className,
  variant = "default",
  hint,
  ...props
}: React.ComponentProps<typeof MenuPrimitive.Item> & { variant?: "default" | "destructive"; hint?: string }) {
  return <MenuPrimitive.Item data-slot="dropdown-menu-item" data-variant={variant} className={cn("ot-menu-item", className)} {...hinted(hint)} {...props} />
}

/** Checked, the sentence turns to the expression italic. Screen readers get aria-checked. */
function DropdownMenuCheckboxItem({ className, hint, ...props }: React.ComponentProps<typeof MenuPrimitive.CheckboxItem> & { hint?: string }) {
  return <MenuPrimitive.CheckboxItem data-slot="dropdown-menu-checkbox-item" className={cn("ot-menu-item", className)} {...hinted(hint)} {...props} />
}

function DropdownMenuRadioItem({ className, hint, ...props }: React.ComponentProps<typeof MenuPrimitive.RadioItem> & { hint?: string }) {
  return <MenuPrimitive.RadioItem data-slot="dropdown-menu-radio-item" className={cn("ot-menu-item", className)} {...hinted(hint)} {...props} />
}

function DropdownMenuLabel({ className, ...props }: React.ComponentProps<typeof MenuPrimitive.Label>) {
  return <MenuPrimitive.Label data-slot="dropdown-menu-label" className={cn("ot-menu-label", className)} {...props} />
}

function DropdownMenuSeparator({ className, ...props }: React.ComponentProps<typeof MenuPrimitive.Separator>) {
  return <MenuPrimitive.Separator data-slot="dropdown-menu-separator" className={cn("ot-menu-sep", className)} {...props} />
}

/**
 * Shortcut keys, each drawn as a base `ot-kbd` cap. A string of one word splits into
 * its characters ("⌘D" is two keys); a string with spaces splits on them ("Shift Tab").
 * A shortcut is a Latin key sequence, so it reads ⌘D left to right on a right-to-left page too.
 */
function DropdownMenuShortcut({ className, children, ...props }: React.ComponentProps<"span">) {
  const keys = typeof children === "string" ? (children.includes(" ") ? children.split(" ") : [...children]) : null
  return (
    <span data-slot="dropdown-menu-shortcut" dir="ltr" className={cn("ot-menu-keys", className)} {...props}>
      {keys ? keys.map((k, i) => <kbd key={i} className="ot-kbd">{k}</kbd>) : children}
    </span>
  )
}

/** Opens something, so it carries the one → glyph. */
function DropdownMenuSubTrigger({ className, hint, ...props }: React.ComponentProps<typeof MenuPrimitive.SubTrigger> & { hint?: string }) {
  return <MenuPrimitive.SubTrigger data-slot="dropdown-menu-sub-trigger" className={cn("ot-menu-item ot-menu-sub", className)} {...hinted(hint)} {...props} />
}

type SubPlace = Pick<React.ComponentProps<typeof MenuPrimitive.SubContent>, "ref" | "sideOffset" | "alignOffset" | "collisionPadding" | "style">

/** The leader a dropped submenu hangs on: --ot-space-4. */
const DROP = 18

/**
 * Where a submenu opens, for all three menus. Beside its item when it fits there, as on a desk.
 * On a narrow screen, where it fits on neither side, it drops open under its item instead, in
 * by the words' inset, the next level of an outline, and hangs from the item on a leader the way
 * the menu hangs from its trigger (data-drop; dropdown-menu.css draws it). Radix fixes a
 * submenu's side (right, or left in right-to-left), so the drop is made from the offsets alone:
 * back across the item, and down by its height. Measured as the submenu opens.
 */
function useSubmenuPlace({ ref, sideOffset = 2, alignOffset = -8, collisionPadding = 20, style }: SubPlace) {
  const look = React.useContext(MenuLook)
  const [drop, setDrop] = React.useState<{ side: number; align: number } | null>(null)
  const place = React.useCallback(
    (node: HTMLDivElement | null) => {
      const item = node && document.getElementById(node.getAttribute("aria-labelledby") ?? "")
      if (!node || !item) return
      const r = item.getBoundingClientRect()
      const pad = typeof collisionPadding === "number" ? collisionPadding : Math.max(collisionPadding.left ?? 0, collisionPadding.right ?? 0)
      const fits = Math.max(document.documentElement.clientWidth - r.right, r.left) - pad - sideOffset >= node.offsetWidth
      item.toggleAttribute("data-drop", !fits) // its arrow turns down
      const next = fits ? null : { side: parseFloat(getComputedStyle(item).paddingInlineStart) - r.width, align: r.height }
      setDrop((was) => (was?.side === next?.side && was?.align === next?.align ? was : next))
    },
    [sideOffset, collisionPadding],
  )
  return {
    ref: useComposedRefs(place, ref),
    sideOffset: drop ? drop.side : sideOffset,
    alignOffset: drop ? drop.align : alignOffset,
    collisionPadding,
    style: drop ? ({ "--ot-pop-gap": `${DROP}px`, ...style } as React.CSSProperties) : style,
    "data-drop": drop ? "" : undefined,
    "data-variant": look === "leaders" ? look : undefined, // a submenu keeps the contents page's leaders
  }
}

function DropdownMenuSubContent({ className, ref, sideOffset, alignOffset, collisionPadding, style, ...props }: React.ComponentProps<typeof MenuPrimitive.SubContent>) {
  const place = useSubmenuPlace({ ref, sideOffset, alignOffset, collisionPadding, style })
  return (
    <MenuPrimitive.Portal>
      <MenuPrimitive.SubContent data-slot="dropdown-menu-sub-content" className={cn("ot-pop ot-menu", className)} {...props} {...place} />
    </MenuPrimitive.Portal>
  )
}

export {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuItem,
  DropdownMenuCheckboxItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubTrigger,
  DropdownMenuSubContent,
  useSubmenuPlace,
  MenuLook,
}
export type { MenuVariant }

@layer components {
  /* ── ot-menu ── a list of words on the popover panel (ot-pop, from popover.css: the
     leader, the in and out); the one you point at is marked with the highlighter.
     Radix moves the highlight (data-highlighted) with the pointer and the arrow keys.
     Dropdown menu, context menu and menubar all wear it. */
  .ot-pop.ot-menu { padding: var(--ot-space-2) 0; min-width: 14rem; }
  .ot-pop.ot-menu > * { animation: ot-arrive var(--ot-moderato) var(--ot-exhale) backwards; animation-delay: calc((sibling-index() - 1) * var(--ot-arpeggio)); }
  .ot-pop.ot-menu[data-state="closed"] > * { animation: none; }

  .ot-menu-item {
    position: relative; display: flex; justify-content: space-between; align-items: baseline; gap: var(--ot-space-6);
    margin: 0; padding: 0.34em var(--ot-space-5); cursor: pointer; user-select: none; outline: 0;
    color: var(--ot-graphite);
    background: linear-gradient(var(--ot-mark), var(--ot-mark)) no-repeat 100% 0 / 0% 100%;
    /* The colour flips with the first frames of the stroke and back after the last, as the link's does, so the words are never pale on yellow. */
    transition: background-size var(--ot-allegro) var(--ot-exhale), background-position 0s, color 0s linear var(--ot-allegro);
  }
  .ot-menu-item:is([data-highlighted], [data-force~="hover"], .ot-menu-sub[data-state="open"]) { background-position: 0 0; background-size: 100% 100%; color: var(--ot-on-mark); transition-delay: 0s; }
  .ot-menu-item:is([dir="rtl"], [dir="rtl"] *) { background-position: 0 0; }
  .ot-menu-item:is([dir="rtl"], [dir="rtl"] *):is([data-highlighted], [data-force~="hover"], .ot-menu-sub[data-state="open"]) { background-position: 100% 0; }

  /* Checked, a sentence is yours: the expression italic. */
  .ot-menu-item:is([data-state="checked"]) {
    font-family: var(--ot-expression); font-style: italic; font-size: calc(var(--ot-expression-scale) * 1em); color: var(--ot-ink);
    line-height: calc(var(--ot-p-lh) / var(--ot-expression-scale)); padding-block: calc(0.34em / var(--ot-expression-scale)); /* the row keeps its height */
  }
  .ot-menu-item[data-state="checked"][data-highlighted] { color: var(--ot-on-mark); }

  /* A destructive item says so in its words; it only sits a little heavier. Red is for errors. */
  .ot-menu-item[data-variant="destructive"] { font-weight: 500; color: var(--ot-ink); }
  .ot-menu-item[data-variant="destructive"][data-highlighted] { color: var(--ot-on-mark); }

  .ot-menu-item[data-disabled] { color: var(--ot-pencil); opacity: 0.55; cursor: not-allowed; pointer-events: none; }

  /* Only a sub-trigger opens something, so only it carries the arrow. */
  .ot-menu-sub::after { content: "→" / ""; font-size: 0.85em; color: var(--ot-pencil); }
  .ot-menu-sub:is([dir="rtl"], [dir="rtl"] *)::after { content: "←" / ""; }
  .ot-menu-sub:is([data-highlighted], [data-state="open"])::after { color: inherit; }

  /* On a narrow screen, with no room beside it, a submenu drops open under its item
     (useSubmenuPlace), in by the words' inset: the next level of an outline. It hangs from
     the item as the menu hangs from its trigger, a callout on a leader after Weingart: the dot
     lands on the marked item's foot and the line drops, over a strip of paper that covers the
     words it passes (and takes their taps). The item's arrow turns down while it is open. */
  .ot-pop.ot-menu[data-drop] { border-top: var(--ot-pop-gap) solid var(--ot-paper); }
  .ot-pop.ot-menu[data-drop]::before, .ot-pop.ot-menu[data-drop]::after { content: ""; position: absolute; pointer-events: none; background: var(--ot-ink); }
  .ot-pop.ot-menu[data-drop]::before { inset-inline-start: var(--ot-pop-lead); bottom: 100%; width: var(--ot-hairline); height: var(--ot-pop-gap); transform-origin: 50% 0; }
  .ot-pop.ot-menu[data-drop]::after { inset-inline-start: calc(var(--ot-pop-lead) - 2px); bottom: calc(100% + var(--ot-pop-gap) - 2.5px); width: 5px; height: 5px; border-radius: 50%; }
  .ot-menu-sub[data-drop][data-state="open"]::after { content: "↓" / ""; }
  @media (forced-colors: active) {
    /* The highlighter is a gradient, which forced colours drops; the system's own highlight stands in. Leaders and orbit mark by other means. */
    .ot-pop.ot-menu:not([data-variant="leaders"], [data-variant="orbit"]) .ot-menu-item:is([data-highlighted], [data-force~="hover"], .ot-menu-sub[data-state="open"]) { forced-color-adjust: none; background: Highlight; color: HighlightText; }
    .ot-pop.ot-menu[data-drop] { border-top-color: Canvas; }
    .ot-pop.ot-menu[data-drop]::before, .ot-pop.ot-menu[data-drop]::after { background: CanvasText; }
  }

  .ot-menu-keys { display: inline-flex; align-items: baseline; gap: var(--ot-space-2); font-size: var(--ot-pp); color: var(--ot-pencil); font-variant-numeric: tabular-nums; }
  .ot-menu-item:is([data-highlighted], [data-force~="hover"]) :is(.ot-menu-keys, .ot-kbd) { color: inherit; }
  /* On the highlighter the caps' corners are drawn in the text's own colour, as the rules follow the ink. */
  .ot-menu-item:is([data-highlighted], [data-force~="hover"]) .ot-kbd { --c: color-mix(in srgb, var(--ot-on-mark) 42%, transparent); }
  .ot-pop.ot-menu:is([data-variant="leaders"], [data-variant="orbit"]) .ot-menu-item .ot-kbd { --c: var(--ot-rule-strong); }

  .ot-menu-label { padding: var(--ot-space-2) var(--ot-space-5) var(--ot-space-1); font-size: var(--ot-pp); line-height: var(--ot-pp-lh); color: var(--ot-pencil); }
  .ot-menu-sep { height: var(--ot-hairline); margin-block: var(--ot-space-2); background: var(--ot-rule); }

  /* ── leaders ── a book's contents page: each word is joined to its keys by a row of leader
     dots, the way a title is joined to its page number. The highlighter stands down; the
     leader of the word you point at inks from the word to its keys (or to the line's end, where
     there are none) and leaves toward them, as the highlighter's stroke does. Submenus keep it. */
  .ot-pop.ot-menu[data-variant="leaders"] .ot-menu-item { --ot-leader: transparent; gap: var(--ot-space-2); white-space: nowrap; background: none; transition: color var(--ot-allegro); }
  .ot-pop.ot-menu[data-variant="leaders"] .ot-menu-item:is(:has(.ot-menu-keys), .ot-menu-sub) { --ot-leader: var(--ot-rule-strong); }
  .ot-pop.ot-menu[data-variant="leaders"] .ot-menu-item::before {
    content: ""; order: 1; flex: 1 0 var(--ot-space-6); align-self: baseline; height: 0.5em;
    background: linear-gradient(var(--ot-ink), var(--ot-ink)) no-repeat 100% 0 / 0% 100%, var(--ot-leader);
    mask: radial-gradient(circle at 50% 84%, #000 0.07em, transparent 0.1em) 0 0 / 0.45em 100% repeat-x;
    transition: background-size var(--ot-allegro) var(--ot-exhale), background-position 0s;
  }
  .ot-pop.ot-menu[data-variant="leaders"] .ot-menu-item > .ot-menu-keys { order: 2; }
  .ot-pop.ot-menu[data-variant="leaders"] .ot-menu-sub::after { order: 3; }
  .ot-pop.ot-menu[data-variant="leaders"] .ot-menu-item:is([data-highlighted], [data-force~="hover"], .ot-menu-sub[data-state="open"]) { color: var(--ot-ink); }
  .ot-pop.ot-menu[data-variant="leaders"] .ot-menu-item:is([data-highlighted], [data-force~="hover"], .ot-menu-sub[data-state="open"])::before { background-position: 0 0; background-size: 100% 100%; }
  .ot-pop.ot-menu[data-variant="leaders"]:is([dir="rtl"], [dir="rtl"] *) .ot-menu-item::before { background-position: 0 0; }
  .ot-pop.ot-menu[data-variant="leaders"]:is([dir="rtl"], [dir="rtl"] *) .ot-menu-item:is([data-highlighted], [data-force~="hover"], .ot-menu-sub[data-state="open"])::before { background-position: 100% 0; }
  .ot-pop.ot-menu[data-variant="leaders"] .ot-menu-item:is([data-highlighted], [data-force~="hover"]) .ot-menu-keys { color: var(--ot-ink); }

  /* ── marginalia ── after "It has to be design.", where small notes hang beside the big
     words on hairline arrows: the word you point at is explained by its hint, set small in a
     narrow ragged column beside the list at that word's height, on an arrow pointing back at
     it. It glides from word to word. Where there's no room beside the list, it stands under
     it as the list's caption, without the arrow. aria-hidden: each item carries its hint as its
     description. */
  .ot-menu-note {
    position: absolute; inset-inline-start: calc(100% + var(--ot-space-3)); top: var(--ot-note-y, 0);
    width: max-content; max-width: 13em; padding-block: var(--ot-space-1); padding-inline: calc(var(--ot-space-5) + var(--ot-space-2)) var(--ot-space-2);
    translate: 0 calc(var(--ot-pp) * var(--ot-pp-lh) / -2 - var(--ot-space-1));
    font-size: var(--ot-pp); line-height: var(--ot-pp-lh); color: var(--ot-graphite); text-wrap: pretty; background: var(--ot-paper); pointer-events: none;
    transition: top var(--ot-moderato) var(--ot-exhale), opacity var(--ot-allegro);
  }
  .ot-menu-note::before, .ot-menu-note::after { content: ""; position: absolute; top: calc(var(--ot-space-1) + var(--ot-pp) * var(--ot-pp-lh) / 2); }
  .ot-menu-note::before { inset-inline-start: 0; width: var(--ot-space-5); height: var(--ot-hairline); background: var(--ot-ink); }
  .ot-menu-note::after { inset-inline-start: 1px; width: 5px; height: 5px; margin-top: -2.5px; border-inline-start: var(--ot-hairline) solid var(--ot-ink); border-block-end: var(--ot-hairline) solid var(--ot-ink); rotate: 45deg; }
  .ot-menu-note:is([dir="rtl"], [dir="rtl"] *)::after { rotate: -45deg; }
  .ot-menu-note[data-empty] { opacity: 0; }
  .ot-menu-note[data-under] { top: calc(100% + var(--ot-space-3)); inset-inline-start: calc(var(--ot-space-5) - var(--ot-space-2)); translate: none; padding-inline-start: var(--ot-space-2); transition: opacity var(--ot-allegro); }
  .ot-menu-note[data-under]::before, .ot-menu-note[data-under]::after { display: none; }

  @media (forced-colors: active) {
    .ot-pop.ot-menu[data-variant="leaders"] .ot-menu-item::before { forced-color-adjust: none; background: linear-gradient(CanvasText, CanvasText) no-repeat 100% 0 / 0% 100%, GrayText; }
    .ot-pop.ot-menu[data-variant="leaders"] .ot-menu-item:not(:has(.ot-menu-keys), .ot-menu-sub)::before { background-color: transparent; }
    .ot-pop.ot-menu[data-variant="leaders"] .ot-menu-item:is([data-highlighted], [data-force~="hover"])::before { background-position: 0 0; background-size: 100% 100%; }
    .ot-menu-note::before { background: CanvasText; }
    .ot-menu-note::after { border-color: CanvasText; }
  }
}
